38	/****************************************************************************
39	 * Name: update_clock
40	 *
41	 * Description:
42	 *   LVGL 定时器回调，每秒读一次系统时间并刷新标签。
43	 *   时间源是 RTC（CONFIG_RTC_DATETIME），未校准时会从 1970 起算。
44	 *
45	 ****************************************************************************/
46	
47	static void update_clock(lv_timer_t *timer)
48	{
49	  char buf[32];
50	  time_t now;
51	  struct tm tm_now;
52	
53	  now = time(NULL);
54	  localtime_r(&now, &tm_now);
55	
56	  snprintf(buf, sizeof(buf), "%02d:%02d:%02d",
57	           tm_now.tm_hour, tm_now.tm_min, tm_now.tm_sec);
58	  lv_label_set_text(g_time_label, buf);
59	
60	  snprintf(buf, sizeof(buf), "%04d-%02d-%02d",
61	           tm_now.tm_year + 1900, tm_now.tm_mon + 1, tm_now.tm_mday);
62	  lv_label_set_text(g_date_label, buf);
63	}
64	
65	/****************************************************************************
66	 * Name: build_ui
67	 *
68	 * Description:
69	 *   搭建界面：黑底 + 居中大号时间 + 下方日期 + 顶部标题。
70	 *   屏幕实测 390x450，这里用居中对齐而非绝对坐标，换屏也不用改。
71	 *
72	 ****************************************************************************/
73	
74	static void build_ui(void)
75	{
76	  lv_obj_t *screen = lv_screen_active();
77	  lv_obj_t *title;
78	
79	  lv_obj_set_style_bg_color(screen, lv_color_black(), LV_PART_MAIN);
80	  lv_obj_set_style_bg_opa(screen, LV_OPA_COVER, LV_PART_MAIN);
81	
82	  title = lv_label_create(screen);
83	  lv_label_set_text(title, "VelaRide AI");
84	  lv_obj_set_style_text_color(title, lv_palette_main(LV_PALETTE_CYAN),
85	                              LV_PART_MAIN);
86	  lv_obj_align(title, LV_ALIGN_TOP_MID, 0, 60);
87	
88	  g_time_label = lv_label_create(screen);
89	  lv_label_set_text(g_time_label, "--:--:--");
90	  lv_obj_set_style_text_color(g_time_label, lv_color_white(), LV_PART_MAIN);
91	  /* 用内置 montserrat 大号字体，不依赖 /etc/data/font 里的 TTF */
92	  lv_obj_set_style_text_font(g_time_label, &lv_font_montserrat_28,
93	                             LV_PART_MAIN);
94	  lv_obj_center(g_time_label);
95	
96	  g_date_label = lv_label_create(screen);
97	  lv_label_set_text(g_date_label, "-------—--");
98	  lv_obj_set_style_text_color(g_date_label,
99	                              lv_palette_main(LV_PALETTE_GREY),
100	                              LV_PART_MAIN);
101	  lv_obj_align_to(g_date_label, g_time_label, LV_ALIGN_OUT_BOTTOM_MID, 0, 20);
102	}
