105	 * Public Functions
106	 ****************************************************************************/
107	
108	int main(int argc, FAR char *argv[])
109	{
110	  lv_nuttx_dsc_t info;
111	  lv_nuttx_result_t result;
112	
113	  /* 若已有快应用（vapp）占用 LVGL，这里必须退出，否则两个实例抢显示驱动
114	   * 会得到 "disp refr_timer is NULL"。先 kill 掉 vapp 再运行本程序。
115	   */
116	
117	  if (lv_is_initialized())
118	    {
119	      printf("LVGL already initialized (vapp running?). "
120	             "Kill the vapp process first.\n");
121	      return -1;
122	    }
123	
124	  lv_init();
125	
126	  lv_nuttx_dsc_init(&info);
127	#ifdef CONFIG_LV_USE_NUTTX_LCD
128	  info.fb_path = "/dev/lcd0";
129	#endif
130	#ifdef CONFIG_INPUT_TOUCHSCREEN
131	  info.input_path = "/dev/input0";
132	#endif
133	
134	  lv_nuttx_init(&info, &result);
135	
136	  if (result.disp == NULL)
137	    {
138	      printf("velaclock: display init failed\n");
139	      return 1;
140	    }
141	
142	  build_ui();
143	
144	  /* 立刻画一次，避免启动后有一秒空白 */
145	
146	  update_clock(NULL);
147	  lv_timer_create(update_clock, 1000, NULL);
148	
149	  while (1)
150	    {
151	      uint32_t idle = lv_timer_handler();
152	      idle = idle ? idle : 1;
153	      usleep(idle * 1000);
154	    }
155	
156	  return 0;
157	}
